do local a=type(EEex_UDEqual)=='function' and type(EEex_Sprite_GetInPortraitID)=='function' and type(EEex_GameObject_Get)=='function';local ids,areas={},{};local selfok,fail,same,diff=0,0,0,0;if a then for i=0,5 do local q,id=pcall(EEex_Sprite_GetInPortraitID,i);if q and type(id)=='number' and id>=0 and id==math.floor(id) and not ids[id] then ids[id]=true;local x,o=pcall(EEex_GameObject_Get,id);if x and o then local y,ar=pcall(function()if o.m_id==id then return o.m_pArea end end);if y and ar then local z,v=pcall(EEex_UDEqual,ar,ar);if z and v==true then selfok=selfok+1;areas[#areas+1]=ar else fail=fail+1 end end end end end;for i=1,#areas do for j=i+1,#areas do local ok,v=pcall(EEex_UDEqual,areas[i],areas[j]);if ok and v==true then same=same+1 elseif ok and v==false then diff=diff+1 else fail=fail+1 end end end end;C:DisplayText('BGX64 AREA api='..tostring(a)..' self='..selfok..' same='..same..' diff='..diff..' errors='..fail) end
